99	    static boolean checkpointNeeded(final boolean enforceCheckpoint,
100	                                    final Map<TopicPartition, Long> oldOffsetSnapshot,
101	                                    final Map<TopicPartition, Long> newOffsetSnapshot) {
102	        // we should always have the old snapshot post completing the register state stores;
103	        // if it is null it means the registration is not done and hence we should not overwrite the checkpoint
104	        if (oldOffsetSnapshot == null) {
105	            return false;
106	        }
107	
108	        if (enforceCheckpoint)
109	            return true;
110	
111	        // we can checkpoint if the difference between the current and the previous snapshot is large enough
112	        long totalOffsetDelta = 0L;
113	        for (final Map.Entry<TopicPartition, Long> entry : newOffsetSnapshot.entrySet()) {
114	            totalOffsetDelta += entry.getValue() - oldOffsetSnapshot.getOrDefault(entry.getKey(), 0L);
115	        }
116	
117	        // when enforcing checkpoint is required, we should overwrite the checkpoint if it is different from the old one;
118	        // otherwise, we only overwrite the checkpoint if it is largely different from the old one
119	        return totalOffsetDelta > OFFSET_DELTA_THRESHOLD_FOR_CHECKPOINT;
120	    }
